const models = [x=>10+2*x,
x=>Math.abs(x-20),
x=>x*(x+3),
x=>9*x*x,
x=>(x-8)/2,
x=>Math.floor((x-12000)/3000),
x=>Math.hypot(3,x-2),
x=>12000+3000*x,
x=>Math.min(6+3*x,30),
x=>6+3*x/60,
x=>(x-6)/3,
x=>x*(12-x),
x=>x*(20-2*x)*(12-2*x),
x=>100*Math.pow(1.2,x),
x=>3-2*Math.cos(Math.PI*x/4),
x=>x-4,
x=>x+4,
x=>8*x+x*x];
function evaluate(id, value) {
 const c=chapters.find(c=>c.id===id);
 if(!c || typeof value!=="number" || !Number.isFinite(value) || value<c.min-1e-9 || value>c.max+1e-9 || Math.abs((value-c.min)/c.step-Math.round((value-c.min)/c.step))>1e-7) throw new RangeError("Masukan di luar pilihan model");
 return models[id-1](value);
}
function formatNumberTex(value){
 if(typeof value!=='number'||!Number.isFinite(value))throw new RangeError('Nilai harus bilangan berhingga');
 return new Intl.NumberFormat('id-ID',{maximumFractionDigits:4}).format(Math.abs(value)<1e-12?0:value).replace(',','{,}').replace(/\./g,'\\,');
}
const api={chapters,evaluate,formatNumberTex};
